// =============================================================
// Server-side socket emit helper
// =============================================================
// Next.js API routes use this to broadcast events authoritatively
// through the chat-service (socket.io). This makes realtime work for
// messages/notifications generated by the BACKEND (Blorp messages,
// gifts, friend requests, admin actions) — not just client-relayed
// broadcasts.
//
// All emits are best-effort: if the chat service is down or slow the
// caller continues normally (realtime is an enhancement, never a
// dependency).

const CHAT_SERVICE_URL =
  process.env.CHAT_SERVICE_URL || process.env.NEXT_PUBLIC_CHAT_SERVICE_URL || 'http://127.0.0.1:3003'

const INTERNAL_EMIT_TOKEN = process.env.INTERNAL_EMIT_TOKEN || 'chrona-internal-emit-2026'

const EMIT_TIMEOUT_MS = 2500

/**
 * Emit a socket event to one or more rooms on the chat service.
 * Resolves `true` when delivered, `false` on any failure (never throws).
 */
export async function emitSocketEvent(
  room: string | string[],
  event: string,
  payload: unknown
): Promise<boolean> {
  const rooms = Array.isArray(room) ? room : [room]
  if (rooms.length === 0) return false

  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), EMIT_TIMEOUT_MS)
  try {
    const res = await fetch(`${CHAT_SERVICE_URL}/api/emit`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ token: INTERNAL_EMIT_TOKEN, rooms, event, payload }),
      signal: controller.signal,
    })
    return res.ok
  } catch (error) {
    // Non-fatal by design — the chat service may be restarting.
    console.warn(
      '[socket-emit] failed (non-fatal):',
      error instanceof Error ? error.message : error
    )
    return false
  } finally {
    clearTimeout(timer)
  }
}

/** Payload shape pushed to `user:{id}` rooms when a notification is created. */
export interface NotificationPushPayload {
  id: string
  userId: string
  type: string
  title: string
  message: string
  data: string | null
  isRead: boolean
  isDismissed: boolean
  createdAt: string
}

/** Push a freshly-created notification to its recipient in realtime. */
export async function pushNotification(userId: string, notification: NotificationPushPayload): Promise<boolean> {
  return emitSocketEvent(`user:${userId}`, 'notification:new', notification)
}

/**
 * Ping a user that a new DM message arrived in one of their conversations.
 * Used to refresh sidebar unread badges / conversation lists live — the
 * chat itself renders through the conversation room events.
 */
export async function pushDmActivity(
  userId: string,
  data: { conversationId: string; preview?: string; fromPersonaName?: string }
): Promise<boolean> {
  return emitSocketEvent(`user:${userId}`, 'dm:new-message', data)
}

/**
 * Check whether a user has muted a conversation (per-conversation mute).
 * Callers use this to skip `dm:new-message` pings (toast / title badge /
 * sidebar refresh) for muted conversations — the message itself is still
 * delivered and stored. Best-effort: any error → treat as NOT muted so
 * a lookup failure can never block message delivery.
 */
export async function isConversationMuted(
  userId: string,
  conversationId: string
): Promise<boolean> {
  try {
    const { db } = await import('@/lib/db')
    const pref = await db.conversationPreference.findUnique({
      where: { userId_conversationId: { userId, conversationId } },
      select: { isMuted: true },
    })
    return pref?.isMuted === true
  } catch {
    return false
  }
}
